-- 케이크별 원재료·원산지·영양성분 (과제용 예시 값)
-- 소은 sample_data(케이크 9~163번)를 넣은 DB에서 실행. 여러 번 실행해도 괜찮음 (있으면 덮어씀)
USE minecake;
ON DUPLICATE KEY UPDATE ingredients=VALUES(ingredients), allergens=VALUES(allergens), serving_basis=VALUES(serving_basis),
  kcal=VALUES(kcal), sugar_g=VALUES(sugar_g), protein_g=VALUES(protein_g), fat_g=VALUES(fat_g),
  sat_fat_g=VALUES(sat_fat_g), sodium_mg=VALUES(sodium_mg), storage=VALUES(storage);
